    // VDAC4: standard message frame and balanced vertical gaps.
    void showMainMenuExitPrompt( const int buttons )
    {
        const char * exitLabel = Settings::Get().getGameLanguage() == "ru" ? _( "Main menu|Quit" ) : "Exit";
        const std::string message = std::string( "F12 - " ) + exitLabel;
        if ( buttons == Dialog::ZERO ) {
            fheroes2::showStandardTextMessage( exitLabel, message, Dialog::ZERO );
            return;
        }
        auto & display = fheroes2::Display::instance();
        Dialog::FrameBox window( 60, true );
        const auto & area = window.GetArea();
        const fheroes2::Text header( exitLabel, fheroes2::FontType::normalYellow() );
        const fheroes2::Text body( message, fheroes2::FontType::normalWhite() );
        const std::string caption = std::string( "ESC - " ) + _( "Cancel" );
        fheroes2::Sprite released, pressed;
        fheroes2::Point releasedOffset, pressedOffset;
        fheroes2::getCustomNormalButton( released, pressed, Settings::Get().isEvilInterfaceEnabled(), { 190, 30 }, releasedOffset, pressedOffset, ICN::STONEBAK );
        fheroes2::ButtonSprite cancel( 0, 0, std::move( released ), std::move( pressed ) );
        const int gap = std::max<int32_t>( 0, ( area.height - header.height() - body.height() - cancel.area().height ) / 4 );
        const int headerY = area.y + gap;
        const int bodyY = headerY + header.height() + gap;
        header.draw( area.x, headerY, area.width, display );
        body.draw( area.x, bodyY, area.width, display );
        cancel.setPosition( area.x + ( area.width - cancel.area().width ) / 2, bodyY + body.height() + gap );
        const fheroes2::Text captionText( caption, fheroes2::FontType::normalWhite() );
        const auto drawCancel = [&]() {
            cancel.draw();
            const auto & buttonArea = cancel.area();
            captionText.draw( buttonArea.x, buttonArea.y + ( buttonArea.height - captionText.height() ) / 2 + ( cancel.isPressed() ? 1 : 0 ), buttonArea.width, display );
        };
        drawCancel();
        display.render();
        auto & le = LocalEvent::Get();
        while ( le.HandleEvents() ) {
            const bool held = le.isMouseLeftButtonPressedAndHeldInArea( cancel.area() );
            if ( held != cancel.isPressed() ) {
                if ( held ) { cancel.press(); } else { cancel.release(); }
                drawCancel();
                display.render( cancel.area() );
            }
            if ( Game::HotKeyCloseWindow() || le.MouseClickLeft( cancel.area() ) ) {
                break;
            }
        }
    }
